"use strict";(globalThis.webpackChunkpolymesh_developer_documentation=globalThis.webpackChunkpolymesh_developer_documentation||[]).push([[19256],{75492(e){e.exports=JSON.parse('{"tag":{"label":"changelog","permalink":"/polymesh-documentation-site/tags/changelog","allTagsPath":"/polymesh-documentation-site/tags","count":23,"items":[{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-asset-freezing","title":"Asset Freezing Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 adds holder-level asset freezing - freeze a single account or portfolio, or part of a holder\'s balance - plus a controller transfer that delivers to a named recipient. v8.1.2 closes the gaps in how that freeze is enforced.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/asset-freezing"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-balances","title":"Balances & Transfers Changelog - v7.4 to v8.0","description":"Breaking changes to the POLYX Balances pallet in Polymesh chain v8 - transfer calls, events, account storage layout, and migration guidance for exchanges, custodians, and wallets.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/balances-and-transfers"},{"id":"developer-resources/changelogs/changelogs-index","title":"Chain Changelogs","description":"Runtime-level changelogs for Polymesh chain releases, covering breaking changes, new features, and migration guidance for node operators and integrators.","permalink":"/polymesh-documentation-site/development/changelogs"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-confidential-assets","title":"Confidential Assets Changelog - v7.4 to v8.0","description":"Polymesh chain v8 adds the new Confidential Assets (PCA) pallet - available on Testnet and Develop, not yet on Mainnet.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/confidential-assets"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-eth-wallets","title":"ETH Wallets Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 supports EVM-keyed accounts as subsidy beneficiaries and MultiSig signers, makes authorization acceptance fee-free for them, and restricts transaction tipping to the Governance Committee.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/eth-wallets"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-pallet-api-reference","title":"Full Pallet API Reference - v7.4 to v8.0","description":"Mechanically generated, pallet-by-pallet reference of every added, removed, and modified call, event, error, storage item, and constant between Polymesh chain v7.4 and v8.0, derived from on-chain runtime metadata.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/pallet-api-reference"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-pallet-api-reference","title":"Full Pallet API Reference - v8.0 to v8.1.2","description":"Pallet-by-pallet reference of every added and modified call, event, error, storage item and runtime API between Polymesh chain v8.0.2 and v8.1.2, including the v8.1.2 permission and settlement fixes.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/pallet-api-reference"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-fungible-asset-precompile","title":"Fungible Asset Precompile Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1 exposes every native fungible asset as an ERC-20 token through a pallet-revive precompile; v8.1.1 completes the ERC-3643 and ERC-7943 surface with pausing, agent checks, partial freezing and recipient-directed forced transfers.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/fungible-asset-precompile"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-identity-and-onboarding","title":"Identity & Onboarding Changelog - v7.4 to v8.0","description":"Breaking changes to the Identity pallet in Polymesh chain v8 - CDD service providers renamed to DID registrars, self-service DID registration, and removal of child identities.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/identity-and-onboarding"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-native-asset-holdings","title":"Native Asset Holdings Changelog - v7.4 to v8.0","description":"Breaking changes to the Asset, NFT, and Portfolio pallets in Polymesh chain v8 - the AssetHolder model that lets accounts hold assets directly, not just portfolios.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/native-asset-holdings"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-nft-approvals","title":"NFT Approvals Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 adds per-token and collection-wide NFT approvals, spender-mode NFT transfers through Settlement::transfer_funds, and NFTApi version 4.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/nft-approvals"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-nft-precompile","title":"NFT Precompile Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 exposes every NFT collection as an ERC-721 token through a pallet-revive precompile, with ERC-721Metadata token URIs, ERC-165 introspection and ERC-7943 transfer checks.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/nft-precompile"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-other-runtime-changes","title":"Other Runtime Changes Changelog - v7.4 to v8.0","description":"Remaining Polymesh chain v8 changes not covered elsewhere - transaction fee pallet split, Sudo, authorized runtime upgrades, the CheckMetadataHash signing extension, Scheduler retries, and new light-client pallets.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/other-runtime-changes"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-other-runtime-changes","title":"Other Runtime Changes Changelog - v8.0 to v8.1.2","description":"Remaining Polymesh chain v8.1.2 runtime changes - the runtime version, storage migrations, re-benchmarked weights, EVM permission checks against the underlying extrinsic, a Grandpa CurrentSetId fix repairing warp sync, and the DART audit report.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/other-runtime-changes"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-overview","title":"Polymesh Chain Changelog - v7.4 to v8.0","description":"Executive summary, breaking-change themes, and migration checklist for upgrading integrations from Polymesh chain v7.4 to v8.0.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-overview","title":"Polymesh Chain Changelog - v8.0 to v8.1.2","description":"Executive summary and migration notes for upgrading integrations from Polymesh chain v8.0 to v8.1.2 - EVM precompiles for fungible assets, NFT collections and general runtime calls, holder-level asset freezing, NFT approvals, ETH wallet support, and the v8.1.2 correctness fixes.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-runtime-precompile","title":"Polymesh Runtime Precompile Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 adds a general-purpose precompile exposing asset creation, ticker registration, DID onboarding and external agent authorization to EVM contracts.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/runtime-precompile"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-relayer-and-subsidies","title":"Relayer & Subsidies Changelog - v7.4 to v8.0","description":"Breaking changes to the Relayer pallet in Polymesh chain v8 - the new approve/accept/revoke subsidy flow, and relay_tx moving from Utility to Relayer.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/relayer-and-subsidies"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-runtime-apis-and-rpc","title":"Runtime APIs & JSON-RPC Changelog - v7.4 to v8.0","description":"Changes to Polymesh\'s state_call runtime APIs (AssetApi, StakingApi, SettlementApi, IdentityApi, and others) and the node\'s JSON-RPC method surface between chain v7.4 and v8.0.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/runtime-apis-and-rpc"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-settlement-and-instructions","title":"Settlement & Instructions Changelog - v7.4 to v8.0","description":"Breaking changes to the Settlement pallet in Polymesh chain v8 - instruction legs, affirmations, and receipts moving from portfolios to the AssetHolder model.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/settlement-and-instructions"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-smart-contracts-evm","title":"Smart Contracts Changelog - v7.4 to v8.0","description":"Polymesh chain v8 adds pallet-revive, a dual-VM (PolkaVM + EVM) smart contract engine, as the only smart contract pallet on Polymesh.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/smart-contracts-evm"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-staking-and-validators","title":"Staking & Validators Changelog - v7.4 to v8.0","description":"Breaking changes to the Staking pallet in Polymesh chain v8 - the new Validators pallet, bond/controller signature changes, paged payouts, and ledger migration.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/staking-and-validators"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-fixes","title":"What Changed in v8.1.2 - Polymesh Chain Changelog","description":"The correctness and permission fixes Polymesh chain v8.1.2 applies on top of v8.1.1 - freeze enforcement in transfer reports and portfolio moves, STO settlement verification, refused Except permissions, and the custody and MultiSig permission checks.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/v8.1.2-fixes"}],"unlisted":false}}')}}]);